  const raw = ((resp.content || []).find(b => b.type === 'text')?.text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').replace(/<thinking>[\s\S]*?<\/thinking>/i, '').trim();
  r = JSON.parse(raw);
} catch(e) {
  return [{ json: { ...d, error: true, message: 'Audit Agent returned invalid JSON.' } }];
}

const rv = r.review;
const se = (s) => s >= 71 ? '🟢' : s >= 41 ? '🟠' : '🔴';
const fmt = (s) => (s/10).toFixed(1) + '/10';
const chk = (v) => v ? '✅' : '❌';
const statusMap = { ship: '🟢 Ready to ship', needs_revision: '🟠 Needs revision', major_revision: '🔴 Major revision needed' };
const verdictMap = { ok: '🟢 All good', needs_sources: '🟠 Sources needed', major_issues: '🔴 Major issues' };

const lines = [
  '### 📊 Full Audit Report', '',
  '**📝 ' + d.title + '**', '🔗 ' + d.link, '', '---', '',
  '#### 1️⃣ Editorial Review — **' + (statusMap[rv.status] || rv.status) + '** (' + fmt(rv.overall_score) + ')',
  '| Dimension | Score |', '|:---|:---:|',
  '| Structure | ' + fmt(rv.structure?.score||0) + ' ' + se(rv.structure?.score||0) + ' |',
  '| Readability | ' + fmt(rv.readability?.score||0) + ' ' + se(rv.readability?.score||0) + ' |',
  '| Engagement | ' + fmt(rv.engagement?.score||0) + ' ' + se(rv.engagement?.score||0) + ' |',
  '| Credibility | ' + fmt(rv.credibility?.score||0) + ' ' + se(rv.credibility?.score||0) + ' |',
  '', '🔧 **Top edits:**',
  ...(rv.top_edits||[]).map((e,i) => (i+1) + '. ' + e),
  '',
  '#### 2️⃣ Key Takeaways',
  '| Check | Status |', '|:---|:---:|',
  '| Block found | ' + chk(r.takeaways?.block_found) + ' |',
  '| Position correct | ' + chk(r.takeaways?.position_correct) + ' |',
  '| Count (3-5) | ' + chk(r.takeaways?.count_ok) + ' (' + (r.takeaways?.count||0) + ') |',
  '| Specific | ' + chk(r.takeaways?.items_are_specific) + ' |'
];
if (r.takeaways?.rewritten_items?.length > 0) {
  lines.push('', '✏️ **Suggested takeaways:**');
  r.takeaways.rewritten_items.forEach((item, i) => lines.push((i+1) + '. ' + item));
}
lines.push('',
  '#### 3️⃣ Sources — **' + (verdictMap[r.sources?.overall_verdict] || r.sources?.overall_verdict || '') + '**',
  '📊 ' + (r.sources?.total_claims||0) + ' claims — ' + (r.sources?.sourced||0) + ' sourced, ' + (r.sources?.unsourced_critical||0) + ' critical'
);
lines.push('',
  '#### 4️⃣ SEO Fields',
  '**Keyphrase:** ' + (r.seo?.keyphrase_changed ? 'Proposed: `' + r.seo.proposed_keyphrase + '`' : '_No change_'),
  '**Meta desc:** ' + (r.seo?.metadesc_changed ? '(' + r.seo.char_count + ' chars) _' + r.seo.proposed_metadesc + '_' : '_No change_')
);

return [{ json: {
  ...d,
  overall_score: rv.overall_score || 0,
  status: rv.status || 'needs_revision',
  result: JSON.stringify(r),
  chat_message: lines.join('\n'),
  error: false
}}];

const d = $input.first().json;
if (!d.title || !d.content_html) {
  return [{ json: { error: true, message: 'Post not found or empty.' } }];
}

const userMsg = `ORIGINAL ARTICLE (raw Gutenberg HTML):
${d.content_html}`;

const llm = d.llm?.rewrite || { model: "claude-sonnet-4-6", max_tokens: 8000 };
const body = {
  ...llm,
  system: "Rewrite the article improving structure, readability, and engagement while preserving the original meaning.
Tailor the content for " + (d.website_context || "a general audience blog") + ".
Tone & Voice Rules:
" + (d.brand_voice || "- Professional yet accessible
- Active voice preferred") + "

CRITICAL WORDPRESS HTML CONSTRAINTS:
1. Do NOT alter the WordPress comment wrappers (e.g., `<!-- wp:paragraph -->`).
2. Do NOT omit any closing tags or wrappers.
3. You may ONLY alter the raw text between the HTML tags.
4. If you break the Gutenberg format, the post will fail to save.


" + (d.agent_prompts?.rewrite?.instructions ? "ADDITIONAL INSTRUCTIONS:
" + d.agent_prompts.rewrite.instructions + "

" : "") + "Return your response using ONLY these exact delimiters — no JSON, no markdown, no explanation:

<<<CONTENT_HTML>>>
[full rewritten Gutenberg HTML here]
<<<END_CONTENT_HTML>>>

<<<EXCERPT>>>
[2-sentence excerpt. Plain text only, no HTML. Maximum 55 words.]
<<<END_EXCERPT>>>",
  messages: [{ role: "user", content: userMsg }]
};
return [{ json: { ...d, claudeBody: JSON.stringify(body) } }];

const resp = $input.first().json;
const d = $('Parse Input').first().json;
const built = $('Build Rewrite Body').first().json;
if (built.error === true) {
  return [{ json: { ...d, error: true, message: 'Rewrite Agent: ' + built.message } }];
}
if (resp.error) {
  const apiText = typeof resp.error === 'string' ? resp.error : (typeof resp.error?.error === 'string' ? resp.error.error : (resp.error?.error?.error?.message || resp.error?.error?.message || resp.error?.description || resp.error?.message || 'no details returned'));
  return [{ json: { ...d, error: true, message: 'Rewrite Agent could not get an answer from the model: ' + apiText } }];
}
const raw = ((resp.content || []).find(b => b.type === 'text')?.text || '').trim();

const htmlMatch = raw.match(/<<<CONTENT_HTML>>>[\s\S]*?<<<END_CONTENT_HTML>>>/);
const excerptMatch = raw.match(/<<<EXCERPT>>>([\s\S]*?)<<<END_EXCERPT>>>/);

if (!htmlMatch) {
  return [{ json: { ...d, error: true, message: 'Rewrite Agent: could not find CONTENT_HTML delimiter.' } }];
}

const content_html = htmlMatch[0].replace('<<<CONTENT_HTML>>>', '').replace('<<<END_CONTENT_HTML>>>', '').trim();
const excerpt = excerptMatch ? excerptMatch[1].trim() : '';

return [{ json: {
  ...d,
  rewritten_html: content_html,
  rewritten_excerpt: excerpt,
  error: false
}}];

const d = $('Parse Rewrite Response').first().json;
const wp = $input.first().json;

if (d.error) return [{ json: { ...d, chat_message: '❌ ' + d.message } }];

if (wp.error || wp.code || (wp.data?.status >= 400)) {
  const saveText = typeof wp.error === 'string' ? wp.error : (typeof wp.error?.error === 'string' ? wp.error.error : (wp.error?.error?.error?.message || wp.error?.error?.message || wp.error?.description || wp.error?.message || wp.message || 'no details returned'));
  return [{ json: { ...d, error: true, message: 'Could not save the rewrite to WordPress: ' + saveText, overall_score: 0, status: '', result: '{}', chat_message: '❌ **Could not save rewrite to WordPress.** Error: ' + saveText } }];
}

const lines = [
  '✅ **Rewrite applied — Pending Review**', '',
  '📝 **' + d.title + '**', '🔗 ' + d.link, '', '---', '',
  'Post saved with status **Pending Review**.',
  '_Original preserved in WordPress revision history._'
];

return [{ json: {
  ...d,
  overall_score: 0,
  status: 'rewritten',
  result: JSON.stringify({ rewrite_applied: true }),
  chat_message: lines.join('\n'),
  error: false
}}];

// Connectivity test: the webhook already answered 200 on receipt. The item goes on to POST Result to WordPress,
// which calls the site back at callback_url with auth_token: the plugin waits for that call and reports the round trip.
const d = $input.first().json;
return [{ json: { ...d, overall_score: 0, status: '', result: '{}' } }];

// Error fallback: a command this workflow has no branch for.
const d = $input.first().json;
const message = d.message || 'This workflow has no step for the "' + (d.command || '') + '" command.';
return [{ json: { ...d, error: true, message, overall_score: 0, status: '', result: '{}', chat_message: '❌ ' + message } }];
